import { useState, useEffect } from "react";
import { useNavigate, useParams } from "react-router-dom";
import LinkioBrand from "../../components/LinkioBrand";
import { getProfileDetails } from "../../services/profilesApi";
import { parseApiError } from "../../services/auth";

export default function CompanyPublicPage() {
  const navigate = useNavigate();
  const { id } = useParams();
  const [tab, setTab] = useState("overview");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [company, setCompany] = useState(null);

  const tabs = ["overview", "jobs", "reviews", "culture"];

  useEffect(() => {
    let cancelled = false;
    const fetchCompany = async () => {
      try {
        const data = await getProfileDetails(id);
        if (cancelled) return;
        setCompany(data);
      } catch (err) {
        if (cancelled) return;
        setError(parseApiError(err, "Unable to load company profile."));
      } finally {
        if (!cancelled) setLoading(false);
      }
    };
    if (id) {
      fetchCompany();
    }
    return () => {
      cancelled = true;
    };
  }, [id]);

  if (loading) {
    return (
      <div className="min-h-screen bg-cream font-sans flex items-center justify-center">
        <p className="text-gray-500 text-sm animate-pulse">Loading company profile...</p>
      </div>
    );
  }

  if (error || !company) {
    return (
      <div className="min-h-screen bg-cream font-sans p-10">
        <div className="max-w-xl mx-auto bg-white rounded-3xl border border-gray-250 p-8 text-center shadow-sm">
          <p className="text-red font-semibold text-lg mb-2">Error</p>
          <p className="text-sm text-gray-500 mb-6">{error || "Company profile not found."}</p>
          <button onClick={() => navigate(-1)} className="px-6 py-2 bg-navy text-white rounded-full text-sm cursor-pointer hover:bg-navy-deep transition-all">
            Go Back
          </button>
        </div>
      </div>
    );
  }

  const initials = company.company_name ? company.company_name.slice(0, 2).toUpperCase() : "CO";

  const getIndustryLabel = (ind) => {
    const choices = {
      TECH: "Technology",
      FINANCE: "Finance & Banking",
      WATER: "Water Industry",
      CONSTRUCTION: "Construction & BTP",
      HEALTHCARE: "Healthcare",
      EDUCATION: "Education",
      RETAIL: "Retail & Commerce",
      ENERGY: "Energy & Oil",
      AGRICULTURE: "Agriculture",
      TRANSPORT: "Transport & Logistics",
      OTHER: "Other"
    };
    return choices[ind] || ind || "Other";
  };

  const getCompanySizeLabel = (size) => {
    const choices = {
      STARTUP: "Start-Up (1-10)",
      SMALL: "Small (11-50)",
      MEDIUM: "Medium (51-200)",
      LARGE: "Large (200+)"
    };
    return choices[size] || size || "Medium";
  };

  const getWilayaLabel = (w) => {
    if (!w) return "Alger";
    return w.charAt(0).toUpperCase() + w.slice(1).replace("_", " ");
  };

  return (
    <div className="min-h-screen bg-cream font-sans">
      <nav className="linkio-topbar px-10">
        <LinkioBrand logoWidth={32} logoHeight={20} wordmarkClassName="font-serif text-base font-semibold text-navy tracking-tight" />
        <div className="flex gap-2">
          <button onClick={() => navigate("/dashboard")} className="px-4 py-1.5 rounded-full bg-navy text-white text-sm hover:bg-navy-deep transition-all cursor-pointer">Dashboard</button>
        </div>
      </nav>

      <div className="px-10 py-4">
        <button onClick={() => navigate(-1)} className="text-sm text-navy hover:underline cursor-pointer">← Back</button>
      </div>

      {/* Card */}
      <div className="mx-10 bg-white rounded-2xl border border-gray-200 overflow-hidden mb-6 shadow-sm">
        <div className="h-40 bg-gradient-to-br from-red to-red-dark relative flex items-start justify-end p-4">
          <div className="absolute inset-0 bg-gradient-to-r from-red/80 to-navy/30 mix-blend-multiply" />
          {company.verified ? (
            <span className="relative z-10 bg-black/40 border border-white/20 text-white text-xs px-3 py-1.5 rounded-full font-medium">★ Verified Company</span>
          ) : (
            <span className="relative z-10 bg-black/45 border border-white/20 text-white text-xs px-3 py-1.5 rounded-full font-medium">Profile Pending Verification</span>
          )}
        </div>
        <div className="px-7">
          <div className="-mt-9 mb-3 relative z-10">
            <div className="w-20 h-20 bg-white border-2 border-white rounded-2xl flex items-center justify-center font-bold text-xl shadow-md overflow-hidden">
              {company.avatar ? (
                <img src={company.avatar} alt="Logo" className="w-full h-full object-cover" />
              ) : (
                <span className="text-gray-700">{initials}</span>
              )}
            </div>
          </div>
          <h1 className="font-serif text-2xl mb-1 text-navy-deep font-semibold">{company.company_name}</h1>
          <p className="text-sm text-gray-500 mb-4 max-w-2xl">{company.bio || "No company description provided yet."}</p>
          <div className="flex gap-5 text-sm text-gray-400 mb-5 flex-wrap">
            <span className="flex items-center gap-1">📍 {getWilayaLabel(company.wilaya)}, {company.address}</span>
            <span className="flex items-center gap-1">🏢 {getIndustryLabel(company.industry)}</span>
            <span className="flex items-center gap-1">👥 {getCompanySizeLabel(company.company_size)} employees</span>
          </div>
          <div className="flex gap-2 pb-5 border-b border-gray-150/50">
            {company.website && (
              <a
                href={company.website.startsWith("http") ? company.website : `https://${company.website}`}
                target="_blank"
                rel="noreferrer"
                className="px-4 py-2 border border-gray-205 hover:border-red hover:text-red rounded-full text-xs font-semibold transition-all cursor-pointer shadow-sm bg-white"
              >
                Visit Website ↗
              </a>
            )}
            <button className="px-4 py-2 border border-gray-205 rounded-full text-xs font-semibold transition-all hover:bg-slate-50 cursor-pointer shadow-sm bg-white">Share</button>
          </div>
          <div className="flex">
            {tabs.map((t) => (
              <button key={t} onClick={() => setTab(t)}
                className={`px-4 py-3.5 text-xs font-bold uppercase tracking-wider border-b-2 transition-all cursor-pointer ${tab === t ? "border-red text-red" : "border-transparent text-gray-400 hover:text-navy"}`}>
                {t === "jobs" ? "Jobs" : t}
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Body */}
      <div className="mx-10 flex flex-col lg:flex-row gap-6 pb-16">
        <div className="flex-1 bg-white rounded-2xl border border-gray-200 p-6 shadow-sm">
          {tab === "overview" && (
            <div>
              <h2 className="font-semibold mb-4 text-navy-deep text-lg">About {company.company_name}</h2>
              <p className="text-sm text-gray-500 leading-relaxed mb-6 whitespace-pre-wrap">
                {company.bio || "Founded on principles of quality and execution, we represent a premium business identity in Algeria."}
              </p>
              <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
                {[{ n: getCompanySizeLabel(company.company_size), l: "Company Size" }, { n: getWilayaLabel(company.wilaya), l: "HQ Location" }, { n: company.verified ? "Verified" : "Pending", l: "Status" }].map((s) => (
                  <div key={s.l} className="bg-cream rounded-xl p-4 text-center border border-gray-150/40">
                    <p className="font-serif text-lg text-navy-deep font-semibold">{s.n}</p>
                    <p className="text-xs text-gray-400 mt-1">{s.l}</p>
                  </div>
                ))}
              </div>
            </div>
          )}

          {tab === "jobs" && (
            <div className="text-center py-10">
              <p className="text-gray-400 text-sm italic">Active job openings will be published here once approved.</p>
            </div>
          )}

          {tab === "reviews" && (
            <div className="text-center py-10">
              <p className="text-gray-400 text-sm italic">Reviews are currently disabled for this company profile.</p>
            </div>
          )}

          {tab === "culture" && (
            <div className="text-center py-10">
              <p className="text-gray-400 text-sm italic">No culture description has been published yet.</p>
            </div>
          )}
        </div>

        <div className="w-full lg:w-72 bg-white rounded-2xl border border-gray-200 p-5 shadow-sm h-fit">
          <h2 className="font-semibold mb-4 text-sm text-navy uppercase tracking-wider pb-2 border-b border-gray-100">Company Details</h2>
          {[
            { l: "Sector", v: getIndustryLabel(company.industry) },
            { l: "Size", v: getCompanySizeLabel(company.company_size) },
            { l: "HQ", v: `${getWilayaLabel(company.wilaya)}, Algeria` },
            company.phone && { l: "Phone", v: company.phone },
            company.website && { l: "Website", v: company.website, red: true, href: company.website.startsWith("http") ? company.website : `https://${company.website}` },
          ].filter(Boolean).map((r) => (
            <div key={r.l} className="flex justify-between py-2.5 border-b border-gray-50 last:border-0 text-xs">
              <span className="text-gray-400 font-medium">{r.l}</span>
              {r.href ? (
                <a href={r.href} target="_blank" rel="noreferrer" className="text-red font-semibold hover:underline truncate max-w-[150px]">{r.v}</a>
              ) : (
                <span className="font-semibold text-gray-800 truncate max-w-[150px]">{r.v}</span>
              )}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
